{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 5,
      "text_ar": "حتى لو انحدرت سيول السماء عليهم، فلم يحن الوقت بعد لكي يذهبوا إلى بابل!",
      "verse": 21
    },
    {
      "chapter": 5,
      "text_ar": "لأنه كم من الوقت مضى منذ أن أرسلني أبي إرميا إلى ضيعة أغريبا لأجلب بعض التين لكي أُعطيه للمرضى بين الشعب؟",
      "verse": 22
    },
    {
      "chapter": 5,
      "text_ar": "فذهبت وأخذته، وعندما أتيت إلى شجرة ما في حر الهجير، جلست لأستريح قليلاً، وأسندت رأسي على السلة ونمت.",
      "verse": 23
    },
    {
      "chapter": 5,
      "text_ar": "ولما استيقظت كشفت سلة التين ظاناً أنني تأخرت، فوجدت التين يقطر حليباً، تماماً كما جمعته.",
      "verse": 24
    },
    {
      "chapter": 5,
      "text_ar": "أما أنت فتزعم أن الشعب قد سُبي إلى بابل.",
      "verse": 25
    }
  ]
}
